export const getSportsFitnessProducts = (): Product[] => SPORTS_FITNESS_PRODUCTS;

export const getFeaturedSportsFitnessProducts = (): Product[] => 
  SPORTS_FITNESS_PRODUCTS.filter(product => product.featured);

export const getSportsFitnessProductsByBadge = (badge: string): Product[] =>
  SPORTS_FITNESS_PRODUCTS.filter(product => product.badge === badge);

export const getSportsFitnessProductsByPriceRange = (min: number, max: number): Product[] =>
  SPORTS_FITNESS_PRODUCTS.filter(product => product.price >= min && product.price <= max);
